using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.EventSystems;using UnityEngine.InputSystem.UI;using System.Collections.Generic;
[DefaultExecutionOrder(-60)] public class WoodlandFieldKitUI:MonoBehaviour {
 public WoodlandInventory inventory;public WoodlandPlayer player;public WoodlandEquipment equipment;public bool Open{get;private set;}public bool Busy=>Open||blend>.001f;
 Canvas canvas;UnityEngine.UI.Text header,details,footer,healthReadout;readonly List<UnityEngine.UI.Button> rows=new List<UnityEngine.UI.Button>();readonly List<FieldItem> visible=new List<FieldItem>();string selected="";int page;float blend;Quaternion previousRotation;Vector3 previousPosition;float previousFov;Vector3 ground;Font font;
 public void Build(){if(canvas)return;font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");var go=new GameObject("Field kit canvas",typeof(RectTransform));go.transform.SetParent(transform,false);canvas=go.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=20;var scale=go.AddComponent<UnityEngine.UI.CanvasScaler>();scale.uiScaleMode=UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1280,720);scale.matchWidthOrHeight=.5f;go.AddComponent<UnityEngine.UI.GraphicRaycaster>();if(!Object.FindFirstObjectByType<EventSystem>()){var es=new GameObject("Field kit input",typeof(EventSystem),typeof(InputSystemUIInputModule));es.GetComponent<InputSystemUIInputModule>().AssignDefaultActions();}
 var panel=new GameObject("Field kit",typeof(RectTransform),typeof(UnityEngine.UI.Image));panel.transform.SetParent(go.transform,false);var rt=(RectTransform)panel.transform;rt.anchorMin=new Vector2(.76f,.06f);rt.anchorMax=new Vector2(.99f,.65f);rt.offsetMin=rt.offsetMax=Vector2.zero;panel.GetComponent<UnityEngine.UI.Image>().color=new Color(.018f,.026f,.022f,.94f);
 header=Text(panel.transform,"FIELD KIT",new Vector2(.05f,.86f),new Vector2(.95f,.98f),17);for(int i=0;i<8;i++){int row=i;float y=.82f-i*.066f;var b=Button(panel.transform,"",new Vector2(.05f,y-.058f),new Vector2(.95f,y),()=>{if(row<visible.Count){selected=visible[row].id;Refresh();}});rows.Add(b);}details=Text(panel.transform,"",new Vector2(.05f,.27f),new Vector2(.95f,.76f),15);footer=Text(panel.transform,"",new Vector2(.05f,.025f),new Vector2(.95f,.1f),13);
 Button(panel.transform,"USE / EQUIP",new Vector2(.05f,.105f),new Vector2(.38f,.15f),UseSelected);Button(panel.transform,"DROP",new Vector2(.40f,.105f),new Vector2(.60f,.15f),DropSelected);var previousPage=Button(panel.transform,"‹",new Vector2(.64f,.105f),new Vector2(.77f,.15f),()=>{page=Mathf.Max(0,page-1);Refresh();});previousPage.gameObject.SetActive(false);var nextPage=Button(panel.transform,"›",new Vector2(.81f,.105f),new Vector2(.95f,.15f),()=>{page++;Refresh();});nextPage.gameObject.SetActive(false);healthReadout=Text(go.transform,"",new Vector2(.03f,.04f),new Vector2(.57f,.30f),15);inventory.Changed+=Refresh;canvas.gameObject.SetActive(false);}
 UnityEngine.UI.Text Text(Transform parent,string text,Vector2 min,Vector2 max,int size){var g=new GameObject("Text",typeof(RectTransform),typeof(UnityEngine.UI.Text));g.transform.SetParent(parent,false);var rt=(RectTransform)g.transform;rt.anchorMin=min;rt.anchorMax=max;rt.offsetMin=rt.offsetMax=Vector2.zero;var t=g.GetComponent<UnityEngine.UI.Text>();t.font=font;t.fontSize=size;t.color=new Color(.76f,.84f,.76f);t.text=text;t.raycastTarget=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;return t;}
 UnityEngine.UI.Button Button(Transform parent,string text,Vector2 min,Vector2 max,UnityEngine.Events.UnityAction action){var g=new GameObject("Action",typeof(RectTransform),typeof(UnityEngine.UI.Image),typeof(UnityEngine.UI.Button));g.transform.SetParent(parent,false);var rt=(RectTransform)g.transform;rt.anchorMin=min;rt.anchorMax=max;rt.offsetMin=rt.offsetMax=Vector2.zero;var image=g.GetComponent<UnityEngine.UI.Image>();image.color=new Color(.1f,.13f,.1f,.55f);var b=g.GetComponent<UnityEngine.UI.Button>();b.targetGraphic=image;b.onClick.AddListener(action);Text(g.transform,text,new Vector2(.025f,0),new Vector2(.98f,1),17);return b;}
 void Start(){Build();}
 void Update(){if(WoodlandDemoControls.Paused)return;var k=Keyboard.current;if(k==null)return;if(k.bKey.wasPressedThisFrame)Toggle();if(Open&&k.escapeKey.wasPressedThisFrame)Close();}
 public bool Toggle(){if(Open){Close();return true;}if(player.cinematicLocked||player.IsReloading||(player.nodeRepair&&player.nodeRepair.Busy)||(player.visorEffects&&player.visorEffects.Busy)||inventory.anatomy.Incapacitated||equipment.ActionBusy)return false;Vector3 forward=player.transform.forward;var start=player.transform.position+Vector3.up*.65f;if(Physics.Raycast(start,forward,1.1f,~0,QueryTriggerInteraction.Ignore)){inventory.Notify("Find clear ground for your pack.");return false;}var place=player.transform.position+forward*.9f;if(!Physics.Raycast(place+Vector3.up,Vector3.down,out var hit,3,~0,QueryTriggerInteraction.Ignore)||hit.normal.y<.7f){inventory.Notify("Find level ground for your pack.");return false;}ground=hit.point+Vector3.up*.04f;previousRotation=player.eye.transform.localRotation;previousPosition=player.eye.transform.localPosition;previousFov=player.eye.fieldOfView;player.pack.position=ground;player.pack.rotation=Quaternion.Euler(0,player.transform.eulerAngles.y+180,0);player.pack.gameObject.SetActive(true);Open=true;Build();var physical=GetComponent<WoodlandPhysicalPack>();if(!physical)physical=gameObject.AddComponent<WoodlandPhysicalPack>();physical.kit=this;physical.inventory=inventory;physical.player=player;physical.Show();canvas.gameObject.SetActive(true);Cursor.lockState=CursorLockMode.None;Cursor.visible=true;Refresh();return true;}
 public void Close(){var physical=GetComponent<WoodlandPhysicalPack>();if(physical)physical.Hide();Open=false;if(canvas)canvas.gameObject.SetActive(false);Cursor.lockState=CursorLockMode.Locked;Cursor.visible=false;inventory.Save();}
 void LateUpdate(){float old=blend;blend=Mathf.MoveTowards(blend,Open?1:0,Time.deltaTime*1.8f);if(blend>0||old>0){float eased=blend*blend*(3-2*blend);player.eye.transform.localPosition=Vector3.Lerp(previousPosition,player.transform.InverseTransformPoint(ground-player.transform.forward*.08f+Vector3.up*1.15f),eased);Vector3 look=ground+Vector3.up*.22f-player.eye.transform.position;Quaternion target=Quaternion.Inverse(player.transform.rotation)*Quaternion.LookRotation(look);player.eye.transform.localRotation=Quaternion.Slerp(previousRotation,target,eased);player.eye.fieldOfView=Mathf.Lerp(previousFov,52,eased);player.pack.position=ground+Vector3.up*(1-eased)*.25f;player.rifle.gameObject.SetActive(false);if(player.adsRifle)player.adsRifle.gameObject.SetActive(false);if(player.focusRifle)player.focusRifle.gameObject.SetActive(false);player.watch.gameObject.SetActive(false);}if(!Open&&blend==0&&old>0){player.pack.gameObject.SetActive(false);player.eye.transform.localRotation=previousRotation;player.eye.transform.localPosition=previousPosition;}}
 public void Refresh(){if(!canvas||!Open)return;healthReadout.text="";visible.Clear();int total=0;foreach(var i in inventory.data.items)if(i.container=="carry")total++;page=Mathf.Clamp(page,0,Mathf.Max(0,(total-1)/8));int offset=0;foreach(var i in inventory.data.items){if(i.container!="carry")continue;if(offset++<page*8)continue;if(visible.Count<8)visible.Add(i);}header.text="BACKPACK\n<size=15>"+inventory.Weight.ToString("F1")+" / "+inventory.Capacity+" kg"+"</size>";for(int n=0;n<rows.Count;n++){rows[n].gameObject.SetActive(false);if(n>=visible.Count)continue;var i=visible[n];var t=rows[n].GetComponentInChildren<UnityEngine.UI.Text>();t.text=inventory.defs[i.kind].name+(i.quantity>1?"  ×"+i.quantity:"");t.color=i.id==selected?Color.white:new Color(.64f,.7f,.66f);}var chosen=inventory.data.items.Find(i=>i.id==selected);details.text=chosen==null?inventory.anatomy.Summary():inventory.defs[chosen.kind].name+"\nCondition "+chosen.condition.ToString("F0")+"% · Contamination "+chosen.contamination.ToString("F0")+"%\n"+(inventory.defs[chosen.kind].description??"");footer.text=equipment.ActionBusy?equipment.ActionLabel:inventory.status+"\nB / Esc close • The world stays active";}
 public void SelectPhysical(string id){selected=id;Refresh();}
 public void UseSelected(){var i=inventory.data.items.Find(x=>x.id==selected);if(i==null||equipment.ActionBusy)return;if(i.kind=="radio"||i.kind=="rifle"||i.kind=="torch"){equipment.Equip(i.kind=="torch"?"handtorch":i.kind);Close();}else equipment.UseSupply(i.kind);}
 public void DropSelected(){var item=inventory.data.items.Find(x=>x.id==selected);if(item==null||equipment.ActionBusy)return;if(item.kind=="suit"||item.kind=="backpack"||item.kind=="rifle"||item.kind=="radio"||item.kind=="torch"||item.attachment=="ears"){inventory.Notify("Keep essential or equipped gear on your person.");return;}var dropped=Newtonsoft.Json.JsonConvert.DeserializeObject<FieldItem>(Newtonsoft.Json.JsonConvert.SerializeObject(item));dropped.id=System.Guid.NewGuid().ToString("N");dropped.quantity=1;item.quantity--;if(item.quantity==0)inventory.data.items.Remove(item);var pos=ground+player.transform.right*.45f+Vector3.up*.06f;var record=new FieldDrop{item=dropped,x=pos.x,y=pos.y,z=pos.z};inventory.data.dropped.Add(record);WoodlandLoot.Spawn(record,inventory.defs[item.kind].name);inventory.Notify("Dropped "+inventory.defs[item.kind].name+" — look at it and press E to recover.");Refresh();}
 void OnDestroy(){if(inventory)inventory.Changed-=Refresh;}
}
